changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Maires et Landräte (>= 50 000 hab.)', 'Maires des villes de 50 000 hab. et plus et Landräte des Landkreise (catégorie DE-AMLR, applicable juillet 2027)', 'de_pep_local_executives', 'PEP', 'https://www.destatis.de', 'de-pep-local-executives', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-local-executives-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'SPARQL', NULL, '{"minPopulation": "50000", "endpoint": "https://query.wikidata.org/sparql"}', 168, 12, 'Destatis (Gemeindeverzeichnis) / CC0 Wikidata', 'Statistisches Bundesamt (Destatis) / Wikidata', 'Anticipation du règlement (UE) 2024/1624 (AMLR). Couvre les ~200 maires (Oberbürgermeister) et ~290 préfets de cantons (Landräte) au-dessus de 50 000 habitants.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Maires et premiers magistrats des communes et villes de 50 000 habitants ou plus (Oberbürgermeister).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-AMLR' AND f.label LIKE 'Maire ou premier magistrat%' AND p.dataset_name = 'de_pep_local_executives';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents de conseil d''arrondissement d''au moins 50 000 habitants (Landräte).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-AMLR' AND f.label LIKE 'Président de conseil d''arrondissement%' AND p.dataset_name = 'de_pep_local_executives';
